<?php
namespace App\Services;use App\Models\{Employee,Company,Designation,Project,EmployeeProjectAssignment};use Carbon\Carbon;use PhpOffice\PhpSpreadsheet\Shared\Date as ExcelDate;
class EmployeeMatchService{public function normalizeId($v):?string{$v=preg_replace('/[^A-Za-z0-9]/','',preg_replace('/\.0$/','',trim((string)$v)));return $v?:null;}public function date($v):?string{if(!$v)return null;try{return is_numeric($v)?Carbon::instance(ExcelDate::excelToDateTimeObject((float)$v))->toDateString():Carbon::parse($v)->toDateString();}catch(\Throwable){return null;}}
public function resolve($class,?string $name){$name=trim((string)$name);return $name?$class::firstOrCreate(['name'=>$name]):null;}public function project(?string $n){return $this->resolve(Project::class,$n);}public function company(?string $n){return $n?Company::firstOrCreate(['name'=>trim($n)],['type'=>'subcontractor']):null;}public function designation(?string $n){return $this->resolve(Designation::class,$n);}public function employee(array $d):Employee{$name=trim($d['name']??'');$iq=$this->normalizeId($d['iqama_no']??null);$pn=$this->normalizeId($d['passport_no']??null);$nn=Employee::normalizeName($name);$e=$iq?Employee::where('iqama_no',$iq)->first():null;$e=$e?:($pn?Employee::where('passport_no',$pn)->first():null);$e=$e?:Employee::where('normalized_name',$nn)->first();$des=$this->designation($d['designation']??null);$co=$this->company($d['company']??null);$pr=$this->project($d['project']??null);$p=array_filter(['employee_code'=>'EMP-'.str_pad((string)((Employee::max('id')??0)+1),5,'0',STR_PAD_LEFT),'name'=>$name,'normalized_name'=>$nn,'iqama_no'=>$iq,'passport_no'=>$pn,'designation_id'=>$des?->id,'company_id'=>$co?->id,'current_project_id'=>$pr?->id,'shift'=>$d['shift']??null,'accommodation'=>$d['accommodation']??null,'doj'=>$this->date($d['doj']??null),'remarks'=>$d['remarks']??null,'source_sheet'=>$d['source_sheet']??null,'status'=>'active'],fn($v)=>$v!==null&&$v!=='');if($e){unset($p['employee_code']);$e->update($p);}else{$e=Employee::create($p);}if($pr)EmployeeProjectAssignment::firstOrCreate(['employee_id'=>$e->id,'project_id'=>$pr->id],['status'=>'active']);return $e;}}
